const f=document.querySelector('iframe');const doc=f?f.contentDocument:document;
const all=[...doc.querySelectorAll('tw-passagedata')].map(p=>p.textContent).join(String.fromCharCode(10));
const out={};
for(const st of ['confidence','fame','academic']){
  // capture the text right AFTER a level gate to infer what it unlocks
  const re=new RegExp('\\$'+st+'\\s*>\\s*[0-9]+[^]{0,70}','g');let m;const ex=[];
  while((m=re.exec(all))!==null){ex.push(m[0].replace(/\s+/g,' ').slice(0,85));if(ex.length>4)break;}
  out[st]=ex;
}
return JSON.stringify(out);
